"""Algorithm C: exact fork-channel evaluator and pinned/flat/leaking classifier.

Given

  * a finite Galois group G (as a list of permutations),
  * a fork F: G -> {0,1} (a conjugation-stable predicate on Frobenius elements),
  * a surjection chi: G -> Z/m onto the relevant cyclic quotient of G^ab,
  * and the dial = the fibre of chi that a congruence class determines,

this module computes the exact mutual information I(dial; F) in bits, and
classifies the fork into one of the three regimes of the trichotomy:

    pinned  : every conditional rate is 0 or 1, and I = H(rate);
    flat    : the conditional rate is constant, and I = 0;
    leaking : otherwise, and 0 < I < H(rate).

It also certifies pinnability structurally, by testing invariance of F under
translation by commutators (the pinning-content criterion): F is pinnable by
some modulus if and only if F(g c) = F(g) for every g in G and c in [G,G].

Complexity: O(|G|^2) for the commutator subgroup and the criterion test,
O(|G|) for the channel itself.
"""

from __future__ import annotations

import itertools
import math
from typing import Callable, Dict, List, Sequence, Tuple

Perm = Tuple[int, ...]


def compose(p: Perm, q: Perm) -> Perm:
    return tuple(p[q[i]] for i in range(len(q)))


def inverse(p: Perm) -> Perm:
    out = [0] * len(p)
    for i, v in enumerate(p):
        out[v] = i
    return tuple(out)


def commutator_subgroup(group: Sequence[Perm]) -> set:
    """Subgroup generated by all commutators [a,b] = a^-1 b^-1 a b."""
    gens = {compose(compose(inverse(a), inverse(b)), compose(a, b))
            for a in group for b in group}
    closure = set(gens)
    frontier = set(gens)
    while frontier:
        new = {compose(x, y) for x in closure for y in frontier} - closure
        closure |= new
        frontier = new
    return closure


def factors_through_abelianization(group: Sequence[Perm],
                                   fork: Callable[[Perm], bool]) -> bool:
    """The pinning-content criterion: invariance under commutator translation."""
    comm = commutator_subgroup(group)
    return all(fork(compose(g, c)) == fork(g) for g in group for c in comm)


def eta(x: float) -> float:
    return 0.0 if x <= 0.0 else -x * math.log2(x)


def entropy(*probs: float) -> float:
    if len(probs) == 1:
        return eta(probs[0]) + eta(1.0 - probs[0])
    return sum(eta(p) for p in probs)


def channel(group: Sequence[Perm], fork: Callable[[Perm], bool],
            chi: Callable[[Perm], int], m: int) -> Dict[str, object]:
    """Exact channel from the dial (value of chi) to the fork.

    Assumes Chebotarev equidistribution: every element of the group is equally
    likely as a Frobenius, so the conditional rate in the fibre chi = t is
    #{g : chi(g) = t and F(g)} / #{g : chi(g) = t}.
    """
    fibres: List[List[Perm]] = [[g for g in group if chi(g) == t] for t in range(m)]
    weights = [len(fib) / len(group) for fib in fibres]
    rates = [sum(1 for g in fib if fork(g)) / len(fib) if fib else 0.0
             for fib in fibres]
    avg = sum(w * r for w, r in zip(weights, rates))
    cond = sum(w * entropy(r) for w, r in zip(weights, rates))
    info = entropy(avg) - cond
    if all(r in (0.0, 1.0) for r in rates):
        regime = "pinned"
    elif len(set(rates)) == 1:
        regime = "flat"
    else:
        regime = "leaking"
    return {"weights": weights, "rates": rates, "rate": avg,
            "information": info, "own_entropy": entropy(avg), "regime": regime,
            "pinnable": factors_through_abelianization(group, fork)}


def leakage_law(p: float, q: float) -> float:
    """The closed form I = H(pq) - p H(q) for a q-thinning of a pinned rate-p fork."""
    return entropy(p * q) - p * entropy(q)


if __name__ == "__main__":
    S4 = [tuple(s) for s in itertools.permutations(range(4))]

    def sign(p: Perm) -> int:
        inv = sum(1 for i in range(len(p)) for j in range(i + 1, len(p)) if p[i] > p[j])
        return 1 if inv % 2 == 0 else -1

    A4 = [p for p in S4 if sign(p) == 1]
    IDENT = (0, 1, 2, 3)
    V4 = [p for p in A4 if compose(p, p) == IDENT]
    C3 = (1, 2, 0, 3)

    def chi(g: Perm) -> int:
        if g in V4:
            return 0
        return 1 if compose(g, inverse(C3)) in V4 else 2

    for name, fork in (("[Frob in V4]", lambda g: g in V4),
                       ("[Frob = e]", lambda g: g == IDENT),
                       ("[Frob is a 3-cycle]", lambda g: g not in V4)):
        out = channel(A4, fork, chi, 3)
        print(f"{name:<22} regime={out['regime']:<8} rate={out['rate']:.4f} "
              f"I={out['information']:.6f} bits  (max {out['own_entropy']:.6f}) "
              f"pinnable={out['pinnable']}")
    print(f"\nleakage law check: H(1/12) - (1/3)H(1/4) = "
          f"{leakage_law(1 / 3, 1 / 4):.6f} bits")
